MISSION = 'Follow the Wild’s mission is to inspire the next generation of wildlife storytellers and foster a deeper connection between people and the natural world through education and storytelling.'
MISSION_FULL = ('<p class="body-copy">'+MISSION+'</p><p class="body-copy">Through scholarships, mentorship and creative resources, we empower emerging creators to share their stories while helping scientists, researchers and wildlife professionals communicate their work to broader audiences.</p>'
  '<p class="body-copy">We also develop accessible educational content and partner with schools and local communities to introduce young people to the wonders of wildlife and the natural world.</p>')

def section(kicker, heading, copy, light=True, ident=''):
 return f'<section class="section {"light" if light else ""}"'+(f' id="{ident}"' if ident else '')+f'><div class="wrap two-col"><div><p class="eyebrow">{kicker}</p><h2 class="reveal">{heading}</h2></div><div>{copy}</div></div></section>'

def steps(kicker, heading, items, light=False):
 cards=''.join(f'<article class="reveal"><span>0{i+1}</span><h3>{title}</h3><p>{copy}</p></article>' for i,(title,copy) in enumerate(items))
 return f'<section class="section {"light" if light else ""}"><div class="wrap"><p class="eyebrow">{kicker}</p><h2 class="reveal">{heading}</h2><div class="steps">{cards}</div></div></section>'

def close(kicker, heading, label, url):
 return f'<section class="closing"><img src="assets/photos/humpback-dive.jpg" alt="A humpback whale beneath the surface" loading="lazy"><div class="wrap"><p class="eyebrow">{kicker}</p><h2 class="reveal">{heading}</h2><a class="button" href="{url}">{label} <span>↗</span></a></div></section>'

home='''<section class="hero reference-hero"><img class="hero-image" src="assets/photos/baby-gorilla.jpg" alt="A young mountain gorilla looking out from the leaves" fetchpriority="high"><div class="hero-content wrap"><h1 aria-label="Follow the Wild"><span class="verb-slot" aria-hidden="true"><span id="hero-verb">Follow</span></span><span class="wild-word" aria-hidden="true"><span class="hero-the">The</span> Wild.</span></h1><div class="hero-bottom"><p>Stories that bring the natural world closer.<br>And the people who tell them.</p><a class="button" href="programs.html">Discover our work</a><a class="button hero-secondary" href="get-involved.html">Get involved</a></div></div><div class="hero-index" aria-hidden="true"><span id="verb-number">01</span> / 04</div></section>'''
home+=section('Our purpose','More curiosity.<br><em>More connection.</em>',f'<p class="body-copy">{MISSION}</p><p class="body-copy">A remarkable animal. A forest close to home. A changing ocean. We bring together the people who know these stories and the creators who can help others discover them.</p><a class="text-link" href="about.html">Why we exist ↗</a>',ident='the-idea')
home+=steps('What we’re building','Back a storyteller.<br><em>Open up a world.</em>',[
 ('Scholarships and mentorship.','Scholarships, mentors and creative resources for aspiring wildlife photographers, filmmakers and creators.'),
 ('Storytelling for science.','Pairing emerging creators with scientists, researchers and wildlife professionals to document their work and share it widely.'),
 ('Education and outreach.','Free wildlife and nature content, made with schools, educators and youth organizations.')])
home+=section('Where stories meet people','In your feed.<br><em>In your world.</em>','<p class="body-copy">A short video can introduce an unfamiliar species. A live conversation can bring a field expert into someone’s home. A longer film can make room for a story that deserves time.</p><p class="body-copy">We’re interested in what each format can teach, and in the voices that help people understand wildlife, wild places and our changing climate.</p><a class="text-link" href="why-it-matters.html">Explore the audience research ↗</a>')
home+='''<section class="photo-strip" aria-label="Stories from the natural world"><figure><img src="assets/photos/filmmaker-river.jpg" alt="A filmmaker working on a riverbank" loading="lazy"><figcaption>THE STORYTELLERS</figcaption></figure><figure><img src="assets/photos/field/tiger-rock.jpg" alt="A tiger moving across a rock ledge" loading="lazy"><figcaption>THE WILDLIFE</figcaption></figure><figure><img src="assets/photos/reflection-jump.jpg" alt="An explorer above a reflective salt flat" loading="lazy"><figcaption>THE WILD PLACES</figcaption></figure></section>'''
home+=close('Help us get started','Good stories need<br><em>people behind them.</em>','Support the work','support.html')
page('index.html','Wildlife, nature & storytelling','Inspiring the next generation of wildlife storytellers through scholarships, mentorship and free wildlife education.',home)

about=hero('Our mission','A world<br>worth <em>knowing.</em>',MISSION,'penguin-colony.jpg')
about+=section('Our mission','Storytellers.<br><em>Science. Learning.</em>',MISSION_FULL)
about+=section('Why storytelling','Before we care,<br><em>we get curious.</em>','<p class="body-copy">The people who spend time with wildlife and wild places have extraordinary stories to tell. Reaching an audience takes another set of skills: finding the right format, making a clear story and giving people a reason to stay.</p><p class="body-copy">Follow The Wild brings those skills together. Our focus is education and public engagement through storytelling, from wildlife photography to creator videos and live conversations.</p>')
about+=steps('Our approach','Field knowledge.<br><em>Creative experience.</em>',[
 ('Support the voices.','Help emerging storytellers develop specific stories rooted in their knowledge of a place, species or environmental issue.'),
 ('Share the craft.','Connect them with experienced creators who can help with structure, production and reaching an audience.'),
 ('Make room for learning.','Create free, accessible wildlife education and bring it to schools, educators and young people.')])
about+=section('A complementary role','Their knowledge.<br><em>A wider conversation.</em>','<p class="body-copy">Scientists, researchers and wildlife professionals do vital work, but don’t always have the time or tools to share it. We plan to pair them with emerging creators who can help document and tell that story.</p><p class="body-copy">Creators get hands-on experience in the field. The research and projects reach a wider audience. Wildlife, oceans, forests and climate all belong in that conversation.</p>')
about+=section('Who this is for','For the curious.<br><em>At every age.</em>','<p class="body-copy">You don’t have to be a creator to be part of Follow The Wild. You might love wildlife photography, want to understand a changing landscape, or simply enjoy discovering something you never knew.</p><p class="body-copy">Our education and outreach work is built for young people: free content about wildlife and the natural world, and partnerships with local schools, educators and youth organizations. Anyone who wants to learn is welcome.</p>',False)
about+=close('Our next step','Start small.<br><em>Tell it well.</em>','See what we’re developing','programs.html')
page('about.html','About','Inspiring the next generation of wildlife storytellers and connecting people with the natural world through education and storytelling.',about)

WK_OVERVIEW='<section class="section wk-overview"><div class="wrap"><p class="eyebrow">Two areas of focus</p><h2 class="reveal">What we’re<br><em>building first.</em></h2><div class="wk-cards">\n<a class="wk-card reveal" href="#scholarship"><img src="assets/photos/kids-explorers.jpg" alt="Two kids exploring outdoors with a map and a camera" loading="lazy"><div class="wk-card-body"><span class="wk-num">01</span><h3>Emerging Storytellers Scholarship &amp; Mentorship</h3><p>Scholarships, mentors and creative resources for aspiring wildlife photographers, filmmakers and creators.</p><span class="wk-go">See the program ↓</span></div></a>\n<a class="wk-card reveal" href="#education"><img src="assets/photos/class-outdoors.jpg" alt="A teacher and students testing pond water outdoors" loading="lazy"><div class="wk-card-body"><span class="wk-num">02</span><h3>Wildlife Education &amp; Outreach</h3><p>Free wildlife education, made with schools, educators and youth organizations.</p><span class="wk-go">See the program ↓</span></div></a>\n</div></div></section>'
WK_SCHOLAR='<section class="section light wk-feature" id="scholarship"><div class="wrap"><div class="wk-split"><figure class="wk-photo reveal"><img src="assets/photos/field/crested-eagle.jpg" alt="A long-crested eagle keeping watch from a dead branch" loading="lazy"><figcaption>Focus area 01</figcaption></figure><div><p class="eyebrow">Focus area 1 / Emerging Storytellers Scholarship &amp; Mentorship</p><h2 class="reveal">A story to tell.<br><em>A little help to tell it.</em></h2><p class="body-copy">Scholarships, mentorship and creative resources help aspiring wildlife photographers, filmmakers and creators develop their stories and share them. A small award can make a real difference. So can time with someone who knows how to turn an idea into a compelling video, photo story or live conversation.</p><p class="body-copy">We’re designing a small first cohort, pairing project support with experienced mentors. We’re especially interested in storytellers with local knowledge, a distinctive perspective and a clear subject they want people to understand.</p><p class="funding-stage">The scholarship program is in development. Applications are not open. Award amounts, eligibility, selection and timing will be announced when confirmed.</p></div></div><p class="eyebrow wk-sub">What a scholarship includes</p><div class="wk-tiles"><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><path d="M8 14h6l3-4h14l3 4h6v22H8z"/><circle cx="24" cy="25" r="7"/></svg><h3>Support for a specific story</h3><p>Help with the costs of making the work: fieldwork, production, editing or access to the right equipment.</p></article><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><circle cx="17" cy="15" r="5"/><circle cx="32" cy="18" r="4"/><path d="M7 38c1-7 5-11 10-11s9 4 10 11"/><path d="M26 37c1-5 3-8 6-8s6 3 7 8"/></svg><h3>Time with a mentor</h3><p>Practical guidance from an experienced storyteller on the idea, the craft and making work for its audience.</p></article><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><path d="M10 20h28v18H10z"/><path d="M18 20v-5h12v5"/><path d="M10 28h28"/></svg><h3>Creative resources</h3><p>Access to equipment, editing help and a clear plan to publish and share the finished work.</p></article></div></div></section>'
WK_PAIR='<section class="section wk-pair" id="partnerships"><div class="wrap two-col"><div><p class="eyebrow">Storytelling partnerships</p><h2 class="reveal">Their research.<br><em>Your story.</em></h2><p class="body-copy">We’re also exploring a program that pairs emerging creators with scientists, researchers and people working in wildlife and wild places who could benefit from storytelling support.</p><p class="body-copy">Creators help document and share that work, gaining hands-on experience while bringing important research and projects to a wider audience.</p></div><div class="wk-diagram reveal" aria-label="An emerging creator and a scientist work together to reach a wider audience"><div class="wk-node"><img src="assets/photos/creators-talk.jpg" alt=""><b>Emerging creator</b><span>Brings the storytelling</span></div><div class="wk-link" aria-hidden="true"><i></i><em>+</em></div><div class="wk-node"><img src="assets/photos/diver.jpg" alt=""><b>Scientist or researcher</b><span>Brings the knowledge</span></div><div class="wk-arrow" aria-hidden="true"></div><div class="wk-node wk-result"><b>A wider audience</b><span>Research people can see, share and understand</span></div></div></div></section>'
WK_EDU='<section class="section light wk-feature" id="education"><div class="wrap"><div class="wk-split wk-flip"><figure class="wk-photo reveal"><img src="assets/photos/field/elephants-play.jpg" alt="Young elephants playing together" loading="lazy"><figcaption>Focus area 02</figcaption></figure><div><p class="eyebrow">Focus area 2 / Wildlife Education &amp; Outreach</p><h2 class="reveal">Free to learn.<br><em>Open to young people.</em></h2><p class="body-copy">We create free, accessible educational content about wildlife and the natural world.</p><p class="body-copy">We plan to partner with local schools, educators and youth organizations to bring these stories to younger audiences, in classrooms and in the places they already watch.</p><a class="text-link" href="get-involved.html">Schools and educators: get in touch ↗</a></div></div><div class="wk-tiles"><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><path d="M8 11c5-2 10-2 16 1v26c-6-3-11-3-16-1z"/><path d="M40 11c-5-2-10-2-16 1v26c6-3 11-3 16-1z"/></svg><h3>Free educational content</h3><p>Wildlife and nature stories anyone can watch, read and use, with no paywall.</p></article><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><path d="M6 20 24 11l18 9-18 9z"/><path d="M13 24v9c6 4 16 4 22 0v-9"/></svg><h3>School and educator partners</h3><p>Working with local schools and teachers to bring these stories into classrooms.</p></article><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><circle cx="16" cy="14" r="4"/><circle cx="32" cy="14" r="4"/><path d="M8 36c0-7 4-12 8-12s8 5 8 12"/><path d="M24 36c0-7 4-12 8-12s8 5 8 12"/></svg><h3>Youth organizations</h3><p>Reaching young people through the groups and programs they already belong to.</p></article></div></div></section>'
WK_REPORT='<section class="section wk-report"><div class="wrap"><div class="two-col"><div><p class="eyebrow">How we’ll report our progress</p><h2 class="reveal">Show the work.<br><em>Share what we learn.</em></h2></div><div><p class="body-copy">As projects launch, we plan to report scholarships awarded, mentoring delivered, educational resources created and work published. We’ll also share available audience measures such as views, watch time and engagement.</p><p class="body-copy">Those figures tell us how stories are being seen. Where a project includes a school session or another direct activity, we’ll report participation and feedback separately. Learning and changes in behavior need their own evidence.</p></div></div><div class="wk-tiles"><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="19" r="9"/><path d="M18 27l-3 13 9-5 9 5-3-13"/></svg><h3>Scholarships awarded</h3><p>Who we supported and what they made.</p></article><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><circle cx="17" cy="15" r="5"/><circle cx="32" cy="18" r="4"/><path d="M7 38c1-7 5-11 10-11s9 4 10 11"/><path d="M26 37c1-5 3-8 6-8s6 3 7 8"/></svg><h3>Mentoring delivered</h3><p>Time spent with experienced storytellers.</p></article><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><path d="M8 11c5-2 10-2 16 1v26c-6-3-11-3-16-1z"/><path d="M40 11c-5-2-10-2-16 1v26c6-3 11-3 16-1z"/></svg><h3>Education resources</h3><p>Free materials created and shared with schools.</p></article><article class="wk-tile reveal"><svg class="wk-icon" viewBox="0 0 48 48" aria-hidden="true"><path d="M10 12h28v24H10z"/><path d="M21 19l9 5-9 5z"/></svg><h3>Stories published</h3><p>Work released and the audiences it reached.</p></article></div><p class="wk-note">Reported as programs launch. No programs have launched yet.</p></div></section>'
work=hero('Our work / In development','Small beginnings.<br><em>Stories that travel.</em>','Two areas of focus: scholarships and mentorship for emerging wildlife storytellers, and free wildlife education for young people.','filmmaker-river.jpg')
work+=WK_OVERVIEW
work+=WK_SCHOLAR
work+=WK_PAIR
work+=WK_EDU
work+=WK_REPORT
work+=close('Be part of the first chapter','A voice. An idea.<br><em>A new connection.</em>','Register your interest','get-involved.html')
page('programs.html','Our work','Emerging Storytellers Scholarship & Mentorship, storytelling partnerships with scientists, and free Wildlife Education & Outreach.',work)

join=hero('For creators and mentors','The wild<br>needs <em>your voice.</em>','Bring your knowledge, your craft and a story you want people to understand.','salt-flat-sunset.jpg')
join+='''<section class="section light"><div class="wrap two-col"><div><p class="eyebrow">An introduction, not an application</p><h2 class="reveal">What would you<br><em>love to tell?</em></h2><p class="body-copy">We’d like to hear from emerging and established storytellers working with wildlife, nature and environmental subjects. Filmmakers, photographers, writers, educators and digital creators all have something to bring.</p><p class="body-copy">We’d also like to hear from scientists, researchers and wildlife professionals who could benefit from storytelling support, and from schools and educators interested in partnering on free wildlife education.</p><p class="body-copy">You might have a project in mind, want to collaborate or be interested in mentoring. Tell us a little about yourself and the work you care about.</p><div class="join-note"><strong>Interested in supporting the work?</strong><p>Individuals, families, foundations and companies can help make the first projects possible.</p><a class="text-link" href="support.html">Ways to support FTW ↗</a></div></div><div class="join-panel"><h3>Start a conversation.</h3><p class="interest-intro">Share your email or Instagram so the team can follow up.</p>'''+interest_form+'''</div></div></section>'''
faq=[('Do I need a large audience?','No minimum audience is required to introduce yourself. We’re interested in a clear story, knowledge of your subject and a willingness to develop your craft. Scholarship eligibility will be published when applications open.'),('What subjects and formats fit?','Wildlife, nature, wild places and environmental topics. We’re interested in films, photography, writing, short videos and live conversations, including work made for YouTube, Instagram, TikTok and streaming platforms.'),('Can I offer to mentor or collaborate?','Yes. Use the idea field to tell us about your experience and how you’d like to contribute.'),('I’m a scientist or researcher. Can you help share my work?','We’re exploring a program that pairs emerging creators with scientists, researchers and wildlife professionals. Tell us about your work in the form.'),('Can schools or educators partner with you?','Yes. We plan to partner with schools, educators and youth organizations on free wildlife education. Introduce yourself and tell us what would help.'),('Can I apply for funding now?','Not yet. This is an interest form, not a funding application. We’ll share confirmed program details and application information when they’re ready.'),('What happens to my details?','The form sends your introduction to the FTW team. We’ll use it to follow up about the community and relevant opportunities. It does not create a paid membership or guarantee funding.')]
join+='<section class="section"><div class="wrap two-col"><p class="eyebrow">A few questions</p><div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq)+'</div></div></section>'
page('get-involved.html','For creators','Introduce yourself to Follow The Wild: emerging storytellers, mentors, scientists and educators working with wildlife, nature and the environment.',join)

support=hero('Support the work','Back the people<br>behind <em>the stories.</em>','Help emerging storytellers make work that brings wildlife and nature to a wider audience.','humpback-dive.jpg')
support+=steps('What support can make possible','A clear purpose<br><em>for every gift.</em>',[
 ('Fund a scholarship.','Help an aspiring wildlife storyteller cover the costs of developing and sharing their story.'),
 ('Make mentoring possible.','Help provide the time, coordination and practical support that connect emerging voices with experienced creators.'),
 ('Create free education.','Support free wildlife education resources and outreach with schools and youth organizations.')],True)
support+=section('Individuals, families and foundations','Help build<br><em>the first chapter.</em>','<p class="body-copy">We’re looking for founding supporters who want to help launch the first scholarships and give FTW a strong start. Support can go toward an agreed project or the work needed to run the program well.</p><p class="body-copy">We’ll discuss the scope, costs and reporting with you before making a commitment.</p><a class="button" href="mailto:sienna@mike-mcgovern.com?subject=Supporting%20Follow%20The%20Wild">Talk to Sienna ↗</a>',False)
support+=section('Companies and creative partners','Bring your resources.<br><em>Share our curiosity.</em>','<p class="body-copy">A company might help fund a scholarship, provide equipment, donate storytelling or creative services, or help a story reach an audience. We’re interested in partnerships with a clear educational purpose and a genuine connection to nature.</p><p class="body-copy">Stories about environmental initiatives should be grounded in evidence, with financial support clearly disclosed. We’ll agree what a partnership makes possible and how it will be acknowledged.</p><a class="text-link" href="mailto:sienna@mike-mcgovern.com?subject=FTW%20partnership">Discuss a partnership ↗</a>')
support+=section('Accountability','Know what<br><em>you’re supporting.</em>','<p class="body-copy">As the first projects launch, we plan to share what was funded, what was made and what we learned. Scholarships, mentorship, educational resources and donated storytelling and creative services will be reported separately.</p><p class="body-copy">We’re developing the first program and funding arrangements. No scholarship recipients, sponsors or launch dates have been announced.</p>',False)
support+='<section class="section light" id="donate"><div class="wrap donation-layout"><div><p class="eyebrow">Online giving / In development</p><h2>Let’s start<br><em>with a conversation.</em></h2><p class="body-copy">Online donations are not available yet. To discuss supporting FTW, contact Sienna using the links above.</p><p class="body-copy">The preview shows a possible future giving experience. It does not accept payments or record pledges.</p></div>'+donation_card+'</div></section>'+donation_dialog
page('support.html','Support us','Support Follow The Wild scholarships, mentorship, free wildlife education and donated creative services. Contact the team to discuss support.',support)

